WITH r AS (
  SELECT time, volume, counter AS read_c FROM windows_logical_disk_read_seconds_total WHERE $__timeFilter(time) AND volume IN ($volume)
), w AS (
  SELECT time, volume, counter AS write_c FROM windows_logical_disk_write_seconds_total WHERE $__timeFilter(time) AND volume IN ($volume)
), joined AS (
  SELECT r.time, r.volume, read_c, write_c FROM r JOIN w ON r.time = w.time AND r.volume = w.volume
), deltas AS (
  SELECT time, volume,
    (read_c - lag(read_c) OVER (PARTITION BY volume ORDER BY time) + write_c - lag(write_c) OVER (PARTITION BY volume ORDER BY time))
    / extract(epoch FROM (time - lag(time) OVER (PARTITION BY volume ORDER BY time))) * 100 AS busy_pct
  FROM joined
)
SELECT time, volume AS metric, busy_pct AS value FROM deltas WHERE busy_pct IS NOT NULL ORDER BY time

WITH lat AS (
  SELECT time, volume, counter AS lat_c FROM windows_logical_disk_read_latency_seconds_total WHERE $__timeFilter(time) AND volume IN ($volume)
), cnt AS (
  SELECT time, volume, counter AS cnt_c FROM windows_logical_disk_reads_total WHERE $__timeFilter(time) AND volume IN ($volume)
), joined AS (
  SELECT lat.time, lat.volume, lat_c, cnt_c FROM lat JOIN cnt ON lat.time = cnt.time AND lat.volume = cnt.volume
), deltas AS (
  SELECT time, volume,
    (lat_c - lag(lat_c) OVER (PARTITION BY volume ORDER BY time)) / NULLIF(cnt_c - lag(cnt_c) OVER (PARTITION BY volume ORDER BY time), 0) * 1000 AS ms
  FROM joined
)
SELECT time, volume || ' — read' AS metric, ms AS value FROM deltas WHERE ms IS NOT NULL ORDER BY time

