WITH info AS (
  SELECT DISTINCT ON (name) name, model, caption FROM windows_diskdrive_info ORDER BY name, time DESC
), size AS (
  SELECT DISTINCT ON (name) name, gauge AS size_bytes FROM windows_diskdrive_size ORDER BY name, time DESC
), parts AS (
  SELECT DISTINCT ON (name) name, gauge AS partitions FROM windows_diskdrive_partitions ORDER BY name, time DESC
)
SELECT i.name AS "Name", i.model AS "Model", i.caption AS "Caption", s.size_bytes AS "Size", p.partitions AS "Partitions"
FROM info i JOIN size s USING (name) JOIN parts p USING (name)
ORDER BY i.name
